package net.onelitefeather.blackhole.backend.evidence.storage;

import java.io.IOException;
import java.io.InputStream;
import java.time.Instant;
import java.util.List;

/**
 * Where the bytes of uploaded evidence files live. The default adapter talks to S3-compatible
 * object storage; a filesystem adapter exists for tiny single-replica setups. Keys are always
 * generated by the server ({@link BlobKeys}), never taken from a client.
 *
 * <p>All methods block; callers run on a blocking executor.
 */
public interface BlobStore {

    /**
     * Stores {@code length} bytes under the key, replacing any existing object. A failed or short
     * write leaves no object behind.
     */
    void put(String key, InputStream content, long length, String contentType) throws IOException;

    /**
     * Opens the bytes {@code start..endInclusive} of the object. The range is clamped to the
     * object's size.
     *
     * @throws NoSuchBlobException if there is no such object
     */
    BlobContent open(String key, long start, long endInclusive) throws IOException;

    /**
     * Deletes the object; deleting a missing object is not an error.
     *
     * @return whether an object existed
     */
    boolean delete(String key) throws IOException;

    /** Every object last modified before the cutoff. */
    List<StoredBlob> listOlderThan(Instant cutoff) throws IOException;

    /**
     * @param stream the requested bytes; the caller closes it
     * @param length how many bytes the stream yields
     */
    record BlobContent(InputStream stream, long length) {
    }

    /** One object in the store. */
    record StoredBlob(String key, Instant lastModified) {
    }

    /** The store has no object under the key. */
    class NoSuchBlobException extends IOException {

        public NoSuchBlobException(String key) {
            super("no such blob: " + key);
        }
    }
}
